## Query Event ID 4625:
# Extract failed Windows authentication events generated by the simulation.
# Extrae los eventos de autenticación fallida generados por la simulación.

Get-WinEvent -FilterHashtable @{
    LogName = "Security"
    Id      = 4625
} -MaxEvents 20 |
    Select-Object TimeCreated,Id,Message |
    Format-List



